struct Params
{
    scalar r1, r2, r3, gamma1, gamma2, k;
    scalar gil, git, gin, gel, get, gen, theta0, theta1;
    scalar sigma0In, sigma0Out, sigmaEps, c0;
    scalar fA[4], hA[3];
    scalar cmAmplitude, cmOmega;
    label solution;
};

enum Zone : label { bloodPool = 0, myocardium = 1, bath = 2 };

//- Outer closure (Params::solution)
enum Solution : label { insulated = 0, grounded = 1 };

inline Params defaultParams()
{
    Params p;
    p.r1 = 0.5;
    p.r2 = 1.0;
    p.r3 = 1.5;
    p.gamma1 = degToRad(20.0);
    p.gamma2 = degToRad(50.0);
    p.k = 3.141592653589793;
    p.gil = 0.17;
    p.git = 0.019;
    p.gin = 0.01;
    p.gel = 0.62;
    p.get = 0.12;
    p.gen = 0.08;
    p.theta0 = degToRad(-20.0);
    p.theta1 = degToRad(90.0);
    p.sigma0In = 0.6;
    p.sigma0Out = 0.25;
    p.sigmaEps = 0.2;
    p.c0 = 0.1;
    p.cmAmplitude = 0.0;
    p.cmOmega = 0.0;
    p.fA[0] = 0.3;
    p.fA[1] = 0.2;
    p.fA[2] = 0.4;
    p.fA[3] = 0.15;
    p.hA[0] = -0.1;
    p.hA[1] = 0.3;
    p.hA[2] = 0.25;
    p.solution = 0;
    return p;
}

