    const scalar w11 = w4 + 3.0/10.0;
    const scalar w12 = fA3*exp((2.0/5.0)*z);
    const scalar w13 = w12*cos(w11);
    const scalar w14 = cos(gamma2);
    const scalar w15 = (w14*w14);
